'use strict';
const DATA=JSON.parse(document.querySelector('#research-data').textContent);
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arr=v=>v==null?[]:Array.isArray(v)?v:[v];
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${({home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',alert:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6m0 3v.2"/>',file:'<path d="M5 3h9l5 5v13H5Z"/><path d="M14 3v6h5M8 13h8m-8 4h6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m5 12 4 4L19 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>'})[name]||''}</svg>`;
const label={full_text:'已读全文',abstract_only:'仅摘要',abstract:'仅摘要',official_record:'官方记录',official_guidance:'官方指导',guidance:'专业指导',narrative_review:'叙述性综述',professional_patient_guidance:'专业患者指导',public_health_guidance:'公共健康指导',human_study:'人体研究',original_research:'原始研究',mechanistic_study:'机制研究',partial:'覆盖不全',missing:'缺证据',covered:'已覆盖',blocked:'未通过',unknown:'待核验',unavailable:'未取得',unassessed:'待评估',frozen:'已冻结',historical:'历史版本',invalidated:'已失效',review:'分支审阅',direction:'方向选择',package:'研究包',support:'支持',counter:'反向线索',counterevidence:'反向线索',limitation:'局限',gap:'保留待补证',keep:'保留',reject:'不采用',adjust:'调整表达',primary:'主方向草案',secondary:'补充草案',supplemental:'补充草案',background:'背景资料',trial_only:'试运行草案',onset:'发生时间',duration:'持续时间',recovery:'恢复时间',progression:'变化过程',missing_reason:'尚缺信息',amplifiers:'加重因素',mitigators:'缓解因素',context:'适用场景',scope:'适用范围',claim_ids:'关联主张',source_ids:'关联来源',note:'说明',assessment:'评估说明',method:'研究方法',independence:'独立性',source_quality:'来源质量',author_fit:'作者适配性',score:'分数',status:'状态',population_limits:'人群限制',publisher_identity:'发布机构',method_basis:'方法依据',limitations:'局限',key_conclusion_eligibility:'关键结论适用性',affiliation_country:'机构所在国',study_population_countries:'研究人群地区'};
const L=v=>label[v]||v||'未记录';
function textValue(v){if(v==null)return '<span class="muted">未记录／待核验</span>';if(Array.isArray(v))return v.length?`<ul class="text-list">${v.map(x=>`<li>${textValue(x)}</li>`).join('')}</ul>`:'<span class="muted">暂无记录</span>';if(typeof v==='object')return `<dl class="details-list">${Object.entries(v).filter(([,x])=>x!==undefined).map(([k,x])=>`<div><dt>${esc(L(k))}</dt><dd>${textValue(x)}</dd></div>`).join('')}</dl>`;return esc(v)}
const tag=(t,c='')=>`<span class="tag ${c}">${esc(t)}</span>`;
const sections=[['home','任务总览',''],['scope','任务设定','01'],['evidence','证据材料','02'],['review','分支审阅','03'],['directions','方向与补证','04'],['delivery','研究交付','05']];
const pageHelpContent={
  home:{purpose:'看清这项研究做到哪、卡在哪，找到下一步。',action:'先确认顶部选中的任务，再看“建议下一步”。新任务从“任务设定”开始，旧任务接着未完成的环节往下做。',role:'串起定范围、查材料、审判断、选方向与补证、交研究包的顺序。',example:'看到“平台兴趣待核验”，就去“方向与补证”看还缺哪些可核验的记录。'},
  scope:{purpose:'先把研究问题说清楚，避免后面越查越散。',action:'确认主题、研究模式、最想回答的问题和不做的范围，再看适用人群与产品角色是否合适。',role:'给后续查资料和分析分支划定范围，明确这次需要回答什么。',example:'“熬夜会带来哪些变化？”从行为出发；“皮肤干燥有哪些可能原因？”从结果出发。',note:'当前原型展示已有设定；新建任务仅演示填写和预览。'},
  evidence:{purpose:'看每条判断凭什么成立，哪些地方还不确定。',action:'按标签找材料，打开详情核对原文、适用人群和局限；有疑问就带到“分支审阅”。',role:'为分支判断提供依据。平台热度只说明关注度，不能证明护肤效果。',example:'查看“熬夜与肤况”的资料时，先核对研究了谁、观察了什么，别只看标题。'},
  review:{purpose:'把一个大问题拆成几条解释，逐条确认哪些有依据、哪些要修改。',action:'选一支，依次看判断、证据和边界；记录保留、调整、不采用或待补证的意见，并写下理由。',role:'把材料变成你审过的判断，再提炼内容方向。关键异议没解决，先别定正式方向。',example:'“这项资料只研究成年人，表达时要保留人群限制。”',note:'当前原型的审阅意见是演示草稿，刷新页面后清除。'},
  directions:{purpose:'从审过的判断中挑选本期值得讲的问题，列出还要查什么。',action:'先看方向的科学依据和平台兴趣；有缺口就切到“待补证”，每次选 1–2 项预览补查要求。',role:'连接专业审阅与最终研究包。证据和兴趣都核验通过后，再确认本期方向；补证围绕具体问题进行。',example:'有科学依据，但缺平台兴趣记录：先补记录，别把“尚不清楚”写成“没人关心”。',note:'补证预览不会启动研究，也不会关闭缺口。'},
  delivery:{purpose:'把选定方向的判断、证据和边界，整理成一份可以独立阅读、继续使用的研究包。',action:'检查结论有没有说过头、来源能否追溯、缺口是否写清，再查看完整研究包和历史版本。',role:'交付本轮研究结果，为后续内容创作提供依据。包已生成，不代表其中的缺口已经解决。',example:'拿到研究包，应能说清“讲什么、凭什么、适用于谁、哪些还不知道”。'}
};
let active=0;const states=DATA.map(d=>({view:'home',branch:d.branches[0].id,branchTab:'overview',evidenceTab:'sources',directionTab:'candidates',candidate:d.candidates[0]?.id,deliveryTab:'summary',query:'',page:1,gapPage:1,gapQuery:'',gapFilter:'all',versionPage:1,selected:new Set(),drafts:{},draftTask:null}));
const D=()=>DATA[active],S=()=>states[active],gaps=()=>D().gaps.filter(g=>g.status!=='closed'),byId=(key,id)=>D()[key].find(x=>x.id===id);
const taskShort=d=>d.mode==='behavior'?'熬夜肌 · 睡眠与护理边界':'干燥紧绷 · 表象与护理顺序';
const tabs=(key,items,value)=>`<div class="tabs" role="tablist" aria-label="当前工作区内容">${items.map(([id,title,count])=>`<button role="tab" id="tab-${key}-${id}" aria-controls="panel-${key}" aria-selected="${value===id}" tabindex="${value===id?'0':'-1'}" data-tab="${key}" data-value="${id}">${title}${count==null?'':`<span class="count">${count}</span>`}</button>`).join('')}</div>`;
const heading=(title,desc,action='')=>`<div class="page-heading"><div class="page-heading-copy"><h1>${title}</h1><p>${desc}</p></div><div class="page-heading-actions">${action}<button class="help-trigger" data-action="page-help" aria-haspopup="dialog" aria-controls="dialog"><svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.2"/></svg><span>使用帮助</span></button></div></div>`;
const goButton=(v,t,primary=false,tab='')=>`<button ${primary?'class="primary"':''} data-go="${v}" ${tab?`data-open-tab="${tab}"`:''}>${t}${primary?icon('arrow'):''}</button>`;
function pager(total,page,key){const last=Math.max(1,Math.ceil(total/5));return `<div class="pagination"><span>${total?`${(page-1)*5+1}–${Math.min(page*5,total)} / ${total} 条`:'0 条'} · 每页 5 条</span><div class="row"><button data-page="${key}" data-delta="-1" ${page<=1?'disabled':''} aria-label="上一页">上一页</button><span class="page-number" aria-label="第 ${page} 页，共 ${last} 页">${page} / ${last}</span><button data-page="${key}" data-delta="1" ${page>=last?'disabled':''} aria-label="下一页">下一页</button></div></div>`}
function refs(key,ids,prefix=''){return `<div class="ref-row">${arr(ids).map(id=>byId(key,id)?`<button class="ref" data-detail="${key}" data-id="${esc(id)}">${prefix}${esc(id.split('-').slice(-1)[0])} ↗</button>`:'').join('')}</div>`}
function render(){const d=D(),s=S();$('#task-switch').innerHTML=DATA.map((x,i)=>`<option value="${i}" ${i===active?'selected':''}>${taskShort(x)} · ${x.mode==='behavior'?'行为型':'结果型'}</option>`).join('');$('#nav').innerHTML=sections.map(([id,title,num],i)=>`${i===1?'<div class="nav-group">研究流程</div>':''}<button class="nav-btn" ${s.view===id?'aria-current="page"':''} data-go="${id}">${num?`<span class="nav-num">${num}</span>`:icon('home')}<span>${title}</span>${id==='directions'?`<span class="nav-count" aria-label="${gaps().length} 项未关闭缺口">${gaps().length}</span>`:''}</button>`).join('');$('#content').innerHTML=({home:home,scope:scope,evidence:evidence,review:review,directions:directions,delivery:delivery}[s.view])();document.title=`${sections.find(x=>x[0]===s.view)[1]} · 护肤研究 UI 原型`;}
function navigate(view,tab){S().view=view;if(tab&&view==='directions')S().directionTab=tab;if(tab&&view==='delivery')S().deliveryTab=tab;closeMenu();render();$('#content').focus({preventScroll:true})}
function home(){const d=D();return heading('任务总览','从当前卡点继续，也可以按左侧顺序查看整项研究。',`<button data-action="new-task">＋ 新建任务</button>`)+`<div class="page-scroll"><div class="task-banner"><div><div class="eyebrow">当前任务 <span class="mono"> / ${esc(d.run_id)}</span></div><h2>${esc(d.task.topic)}</h2><div class="row wrap">${tag(d.mode==='behavior'?'行为型研究':'结果型研究','blue')}${tag('含关键缺口 · 试运行','warn')}<span class="small muted">研究资料更新于 2026.09.25</span></div></div></div><div class="home-grid"><section class="next-action"><span class="eyebrow">建议下一步</span><span class="index">NEXT / 04</span><h2>先明确待补证项，<br>再推进候选方向。</h2><p>两类研究门槛尚未满足。查看 ${gaps().length} 项未关闭缺口，明确下一轮需要补什么，避免重复浏览所有材料。</p><div class="btn-row">${goButton('directions','查看待补证项',true,'gaps')}<button class="linkbtn" data-go="review">先看分支判断 →</button></div></section><section class="surface compact-block"><div class="row between"><h3>当前卡在哪里</h3>${tag('正式交付受阻','warn')}</div><div class="issue">${icon('alert')}<div><h3>科学证据尚未通过</h3><p>分支覆盖、来源质量及适用边界仍有缺口。</p></div></div><div class="issue">${icon('alert')}<div><h3>平台兴趣还不能判断</h3><p>缺少可核验的原页日期、指标与可比基线。</p></div></div><div class="stats-row"><div class="stat"><strong>${d.sources.length}</strong><span>科学来源</span></div><div class="stat"><strong>${d.branches.length}</strong><span>研究分支</span></div><div class="stat"><strong>${d.candidates.length}</strong><span>方向草案</span></div></div><button class="linkbtn small" data-go="delivery">已有试运行研究包，查看内容 →</button></section></div><section class="home-foot"><div class="row between"><h3>这项研究怎么使用</h3><span class="small muted">随时切换，不必从头重来</span></div><div class="flow">${[['scope','确定范围','已设定'],['evidence','查阅材料',`${d.sources.length} 份来源`],['review','逐支判断',`${d.branches.length} 支有缺口`],['directions','方向与补证','当前待推进'],['delivery','查看研究包','试运行版本']].map(([v,t,st],i)=>`<button class="flow-step ${i===3?'current':''}" data-go="${v}"><span class="step">0${i+1}</span><strong>${t}</strong><small>${st}</small></button>`).join('')}</div></section></div>`}
function scope(){const d=D();return heading('任务设定','先明确研究什么，以及哪些结论不在本次范围。',`<button data-action="new-task">＋ 新建任务</button>`)+`<div class="page-scroll"><div class="scope-grid"><section class="surface pad"><div class="row between"><h3>研究范围</h3>${tag('现有任务 · 只读')}</div><dl class="details-list"><div><dt>研究主题</dt><dd>${esc(d.task.topic)}</dd></div><div><dt>研究模式</dt><dd>${d.mode==='behavior'?'行为型 · 从行为出发，追问影响与可改变因素':'结果型 · 从表象出发，区分原因、边界与护理顺序'}</dd></div><div><dt>这次希望回答</dt><dd>${esc(d.task.objective)}</dd></div><div><dt>适用人群</dt><dd>一般成年人 · 日常护肤科普 · 非个体诊疗</dd></div><div><dt>产品角色</dt><dd>${esc(d.task.product_role)}</dd></div></dl></section><section class="surface pad"><h3>先围绕这几个问题</h3><ol class="step-list">${d.task.core_questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ol><hr class="rule"><div class="section-label">明确不做</div>${textValue(d.task.exclude)}<div class="note mt">本页展示当前任务范围；新建任务可以先体验填写与范围预览。</div></section></div><div class="btn-row mt">${goButton('evidence','下一步：查阅证据',true)}</div></div>`}
function evidence(){const d=D(),s=S(),tab=s.evidenceTab;const items=[['sources','科学来源',d.sources.length],['claims','研究主张',d.claims.length],['signals','平台线索',d.signals.length],['knowledge','知识库对照',null]];let html=heading('证据材料','先找需要的材料，打开详情核对来源与局限。')+tabs('evidenceTab',items,tab);if(tab==='knowledge'){const kb=arr(d.knowledge_base)[0]||{},queries=kb.queries||kb.query_terms||[];return html+`<div class="page-scroll surface pad" role="tabpanel" id="panel-evidenceTab" aria-labelledby="tab-evidenceTab-knowledge"><div class="row between"><h2>本次限定查询：未匹配</h2>${tag('只读对照')}</div><p class="muted mt">未匹配不等于整个知识库没有相关知识。</p><dl class="details-list"><div><dt>查询词</dt><dd>${queries.length?textValue(queries):'见当前包的知识库对照记录'}</dd></div><div><dt>检索范围</dt><dd>主张文本及关联来源标题的字面匹配；未覆盖全文、同义词和语义检索。</dd></div><div><dt>匹配条数</dt><dd>0 条 · 本轮真实只读导出</dd></div><div><dt>后续使用</dt><dd>研究包保留候选入库附件，需要单独评估，不自动写入知识库。</dd></div></dl><button class="linkbtn mt" data-detail="knowledge" data-id="knowledge">查看完整对照信息 →</button></div>`}
const query=s.query.trim().toLowerCase();const all=d[tab].filter(x=>JSON.stringify(x).toLowerCase().includes(query));const total=all.length;s.page=Math.min(s.page,Math.max(1,Math.ceil(total/5)));html+=`<div class="page-body" role="tabpanel" id="panel-evidenceTab" aria-labelledby="tab-evidenceTab-${tab}"><div class="toolbar"><div class="searchbox">${icon('search')}<input id="material-search" data-input="query" type="search" aria-label="搜索当前材料" placeholder="搜索标题、主张或资料编号" value="${esc(s.query)}"></div><span class="small muted">${tab==='signals'?'索引线索不能代表真实兴趣':'只显示当前类别，每次打开一条详情'}</span></div><div class="table-wrap"><div class="list-header"><span>${items.find(x=>x[0]===tab)[1]}</span><span>状态 / 操作</span></div>${total?all.slice((s.page-1)*5,s.page*5).map(x=>materialRow(x,tab)).join(''):`<div class="empty"><strong>没有找到匹配材料</strong><p>换一个词，或清除当前搜索。</p><button class="mt" data-action="clear-search">清除搜索</button></div>`}</div>${pager(total,s.page,'page')}</div>`;return html}
function materialRow(x,key){let title=x.title||x.text||x.indexed_title||`${x.platform} 平台线索`,summary=x.excerpt_or_summary||x.allowed_expression||x.missing_reason||'',status=key==='sources'?L(x.read_level):key==='signals'?'兴趣待核验':'需限定表达';return `<article class="data-row"><div class="grow"><div class="meta"><span class="mono muted">${esc(x.id)}</span>${tag(status,key==='signals'?'warn':'')}</div><h3><button class="linkbtn" data-detail="${key}" data-id="${esc(x.id)}">${esc(title)}</button></h3><p class="description clamp">${esc(Array.isArray(summary)?summary.join('；'):summary)}</p></div><div class="trailing"><button class="linkbtn small" data-detail="${key}" data-id="${esc(x.id)}">查看详情 ↗</button></div></article>`}
function branchChoices(){const d=D(),s=S();return `<div class="branch-list" aria-label="选择研究分支">${d.branches.map((b,i)=>`<button class="branch-item" aria-pressed="${s.branch===b.id}" data-branch="${esc(b.id)}"><span class="mono muted">分支 0${i+1}</span><h3>${esc(b.title)}</h3><div class="row between">${tag(s.drafts[b.id]?'已有演示草稿':'保留待补证',s.drafts[b.id]?'blue':'warn')}<span class="small muted">${b.source_ids.length} 来源</span></div></button>`).join('')}</div>`}
function review(){const b=byId('branches',S().branch),i=D().branches.indexOf(b),s=S();return heading('分支审阅','一次审一支：看判断，核证据，明确边界，再记录意见。',`<span class="small muted">${i+1} / ${D().branches.length} 支</span>`)+`<div class="split">${branchChoices()}<article class="detail"><div class="detail-head"><div class="row between"><span class="mono muted">${esc(b.id)}</span>${tag('覆盖不全','warn')}</div><h2>${esc(b.title)}</h2>${tabs('branchTab',[['overview','判断概览'],['claims','主张与证据'],['bounds','适用边界'],['records','审阅记录']],s.branchTab)}</div><div class="detail-scroll" role="tabpanel" id="panel-branchTab" aria-labelledby="tab-branchTab-${s.branchTab}">${branchContent(b)}</div><footer class="detail-foot"><span class="muted small">${s.drafts[b.id]?'已有本页演示草稿 · 真实记录未改动':'现有结论由主控代理审阅，仍保留缺口'}</span><button class="primary" data-action="review-form">记录审阅意见 ${icon('arrow')}</button></footer></article></div>`}
function branchContent(b){const tab=S().branchTab;if(tab==='overview')return `<div class="judgment"><h3>当前判断</h3><p>${esc(b.preliminary_judgment)}</p></div><section class="subsection"><h3>这一支研究什么</h3><p class="prose">${esc(b.definition)}</p></section><section class="subsection"><h3>为什么放在这个位置</h3><p class="prose">${esc(b.priority_rationale)}</p><div class="note mt">${esc(b.chain_position)}</div></section><section class="subsection"><div class="row between"><h3>仍有待补证项</h3><button class="linkbtn small" data-branch-gaps="${esc(b.id)}">在补证队列中查看 →</button></div>${b.gaps.filter(id=>gaps().some(g=>g.id===id)).map(id=>`<div class="kv"><span class="mono">${esc(id.split('-').pop())}</span><span>${esc(byId('gaps',id)?.description)}</span></div>`).join('')}</section>`;
if(tab==='claims')return `<div class="note" style="margin-bottom:20px">先看主张的限定表达，再打开来源核对原文；来源数量不代表证据已足够。</div>${b.claim_ids.map(id=>byId('claims',id)).filter(Boolean).map(c=>`<section class="claim"><span class="mono muted">${esc(c.id)}</span><h3>${esc(c.text)}</h3><div class="small muted">允许表达：${esc(arr(c.allowed_expression).join('；')||'待核验')}</div>${refs('sources',c.source_refs.map(r=>r.source_id),'来源 ')}<button class="linkbtn small mt" data-detail="claims" data-id="${esc(c.id)}">查看主张边界与反向线索 →</button></section>`).join('')}<section class="subsection mt"><h3>支持与反向线索</h3>${b.support?`<div class="section-label">支持依据</div>${textValue(b.support)}`:''}<div class="section-label mt">反向线索／限制</div>${textValue(b.counterevidence||b.counter_source_ids||'本支尚无完成核验的反向来源记录')}${refs('sources',b.source_ids,'关联来源 ')}</section>`;
if(tab==='bounds')return `<dl class="details-list"><div><dt>人群与场景</dt><dd>${textValue(b.population)}${b.context?`<p class="muted small mt">${esc(b.context)}</p>`:''}</dd></div><div><dt>上游因素</dt><dd>${textValue(b.upstream)}</dd></div><div><dt>下游推断边界</dt><dd>${textValue(b.downstream)}</dd></div><div><dt>时间尺度</dt><dd>${textValue(b.time_scale)}</dd></div><div><dt>加重／缓解因素</dt><dd>${textValue(b.modifiers)}</dd></div><div><dt>排除项</dt><dd>${textValue(b.exclusions)}</dd></div>${b.forbidden_expression?`<div><dt>不能这样表达</dt><dd>${textValue(b.forbidden_expression)}</dd></div>`:''}${b.solution_path?`<div><dt>护理路径与产品角色</dt><dd>${textValue(b.solution_path)}<p class="small muted mt">${esc(b.product_role)}</p></dd></div>`:''}</dl>`;
let draft=S().drafts[b.id];return `${draft?`<section class="judgment"><h3>本页演示草稿 · 不是真实审核</h3><strong>${esc(L(draft.action))}</strong><p class="small mt">${esc(draft.reason)}</p></section>`:''}<div class="note">以下为研究包已有的代理审阅记录；不代表用户亲自或临床专家确认。</div>${D().decisions.filter(x=>x.branch_id===b.id).map(x=>`<section class="claim mt"><div class="row between"><span class="mono muted">${esc(x.id)}</span>${tag(L(x.action))}</div><p class="prose mt">${esc(x.reason)}</p><p class="small muted mt">${esc(x.actor_label||'主控代理')} · ${esc(x.decided_at||'未记录时间')}</p></section>`).join('')}`}
function directions(){const s=S(),d=D();let h=heading('方向与补证','科学证据和平台兴趣分别核验；有缺口的方向先保留为草案。')+tabs('directionTab',[['candidates','候选方向',d.candidates.length],['gaps','待补证',gaps().length]],s.directionTab);if(s.directionTab==='gaps')return h+gapList();const c=byId('candidates',s.candidate)||d.candidates[0];return h+`<div class="candidate-layout" role="tabpanel" id="panel-directionTab" aria-labelledby="tab-directionTab-candidates"><div class="branch-list" aria-label="选择方向草案">${d.candidates.map((x,i)=>`<button class="branch-item" data-candidate="${esc(x.id)}" aria-pressed="${x.id===c.id}"><span class="mono muted">方向 0${i+1}</span><h3>${esc(x.title)}</h3>${tag(x.id===d.package.primary_candidate_id?'当前主方向草案':'备选／补充草案',x.id===d.package.primary_candidate_id?'blue':'')}</button>`).join('')}</div><article class="detail"><div class="detail-head"><span class="mono muted">${esc(c.id)}</span><h2>${esc(c.title)}</h2></div><div class="detail-scroll"><div class="note">当前仅可作为含缺口的研究草案，尚未获得正式候选资格。</div><div class="gate-grid">${[['science_gate','科学证据','未通过'],['interest_gate','平台兴趣','待核验']].map(([k,t,st])=>`<div class="gate"><span class="small muted">${t}</span><strong>${st}</strong><p>${esc(arr(c[k]?.reasons).join('；'))}</p></div>`).join('')}</div><section class="subsection"><h3>可以怎样表达</h3>${textValue(c.allowed_expression)}</section><section class="subsection"><h3>不能怎样表达</h3>${textValue(c.forbidden_expression)}</section><section class="subsection"><h3>关联的研究分支</h3><div class="ref-row">${c.branch_ids.map(id=>`<button class="ref" data-open-branch="${esc(id)}">${esc(byId('branches',id)?.title||id)} →</button>`).join('')}</div></section></div><footer class="detail-foot"><span class="small muted">正式准入尚未满足</span><button class="primary" data-candidate-gaps="${esc(c.id)}">查看相关缺口 ${icon('arrow')}</button></footer></article></div>`}
function gapFiltered(){const s=S();return gaps().filter(g=>JSON.stringify(g).toLowerCase().includes(s.gapQuery.toLowerCase())).filter(g=>s.gapFilter==='all'||s.gapFilter==='science'&&!/interest|platform/.test(g.category)||s.gapFilter==='interest'&&/interest|platform/.test(g.category)||s.gapFilter.startsWith('ids:')&&s.gapFilter.slice(4).split(',').includes(g.id))}
function gapList(){const s=S(),all=gapFiltered();s.gapPage=Math.min(s.gapPage,Math.max(1,Math.ceil(all.length/5)));return `<div class="page-body" role="tabpanel" id="panel-directionTab" aria-labelledby="tab-directionTab-gaps"><div class="toolbar"><div class="searchbox">${icon('search')}<input id="gap-search" type="search" data-input="gapQuery" aria-label="搜索待补证项" value="${esc(s.gapQuery)}" placeholder="搜索缺口或编号"></div><select id="gap-filter" aria-label="筛选补证类别"><option value="all" ${s.gapFilter==='all'?'selected':''}>全部类别</option><option value="science" ${s.gapFilter==='science'?'selected':''}>科学与流程缺口</option><option value="interest" ${s.gapFilter==='interest'?'selected':''}>平台兴趣缺口</option>${s.gapFilter.startsWith('ids:')?`<option value="${esc(s.gapFilter)}" selected>当前关联项</option>`:''}</select><span class="small muted" style="margin-left:auto">最多选 2 项</span></div><div class="table-wrap"><div class="list-header"><span>未关闭项 · 点击查看完整要求</span><span>缺口级别</span></div>${all.length?all.slice((s.gapPage-1)*5,s.gapPage*5).map(g=>`<article class="data-row"><input type="checkbox" aria-label="选择 ${esc(g.id)}" data-gap="${esc(g.id)}" ${s.selected.has(g.id)?'checked':''}><div class="grow"><div class="meta"><span class="mono muted">${esc(g.id)}</span><span class="small muted">${/interest|platform/.test(g.category)?'平台兴趣':'科学与流程'}</span></div><h3><button class="linkbtn clamp" data-detail="gaps" data-id="${esc(g.id)}">${esc(g.description)}</button></h3></div><div class="trailing">${tag(g.critical?'关键缺口':'待处理',g.critical?'warn':'')}</div></article>`).join(''):'<div class="empty"><strong>当前筛选没有结果</strong><button class="mt" data-action="clear-gaps">清除筛选</button></div>'}</div>${pager(all.length,s.gapPage,'gapPage')}<div class="detail-foot surface mt"><span class="small muted" id="selection-count">已选 ${s.selected.size} / 2 项 · 仅生成交接预览</span><div class="btn-row"><button class="linkbtn small" data-action="clear-selection" ${s.selected.size?'':'disabled'}>清空选择</button><button class="primary" data-action="request-preview" ${s.selected.size?'':'disabled'}>预览补证要求 ${icon('arrow')}</button></div></div></div>`}
function delivery(){const d=D(),s=S();let h=heading('研究交付','集中查看当前研究包；历史记录在独立标签页中保留。')+tabs('deliveryTab',[['summary','当前研究包'],['history','版本历史',d.snapshots.length]],s.deliveryTab);if(s.deliveryTab==='history'){const all=[...d.snapshots].reverse(),p=s.versionPage;return h+`<div class="page-body" role="tabpanel" id="panel-deliveryTab" aria-labelledby="tab-deliveryTab-history"><div class="note" style="margin:18px 0">历史冻结只读保留，不用新判断覆盖旧记录。完整审计载荷见原始研究包。</div><div class="table-wrap"><table class="history"><thead><tr><th>冻结版本</th><th>类型</th><th>状态</th><th class="hide-mobile">记录时间（原始）</th><th></th></tr></thead><tbody>${all.slice((p-1)*5,p*5).map(x=>`<tr><td><span class="mono">${esc(x.id)}</span></td><td>${L(x.kind)}</td><td>${tag(L(x.status),x.status==='frozen'?'blue':'')}</td><td class="hide-mobile mono">${esc(x.created_at)}</td><td><button class="linkbtn" data-detail="snapshots" data-id="${esc(x.id)}">详情</button></td></tr>`).join('')}</tbody></table></div>${pager(all.length,p,'versionPage')}</div>`}
return h+`<div class="page-scroll" role="tabpanel" id="panel-deliveryTab" aria-labelledby="tab-deliveryTab-summary"><div class="delivery-layout"><section class="surface pad"><div class="row between"><h2>当前研究摘要</h2>${tag('试运行包','warn')}</div><p class="prose mt">${esc(d.package.synthesis)}</p><hr class="rule"><h3>建议的解释顺序</h3><div class="steps-chain">${arr(d.package.knowledge_chain).map((x,i)=>`<div class="chain-item"><b>0${i+1}</b><div><h3>${esc(x.label||x.title)}</h3><p>${esc(x.content||x.solution_path)}</p><button class="linkbtn small" data-open-branch="${esc(x.branch_id)}">回看研究分支 →</button></div></div>`).join('')}</div><p class="small muted mt">${esc(d.package.chain_note)}</p></section><aside class="stack"><section class="surface pad"><h3>这份包可以用在哪里</h3><p class="small muted mt">内部理解、补证和继续审阅。当前尚不能作为正式合格选题。</p><div class="kv"><span>科学证据</span><span>${tag('未通过','warn')}</span></div><div class="kv"><span>平台兴趣</span><span>${tag('待核验','warn')}</span></div><div class="kv"><span>未关闭项</span><span>${gaps().length} 项</span></div><button class="primary mt" data-go="directions" data-open-tab="gaps">返回补证 ${icon('arrow')}</button></section><section class="surface pad"><h3>查看已有文件</h3><p class="small muted mt">这里打开现有版本，不包含本页的演示草稿。</p><div class="btn-row mt"><a class="primary small" href="${esc(d.run_id)}.html" target="_blank" rel="noopener">打开完整研究包 ↗</a><a class="small" href="${esc(d.run_id)}.json" download>下载原始 JSON ↓</a></div><p class="mono muted mt">${esc(d.revision)}</p></section></aside></div><div class="surface pad mt"><h3>表达边界</h3>${textValue(d.package.expression_boundaries)}</div></div>`}
let dialogReturn=null,dialogTrail=[];
function showDialog(title,body,footer='',nested=false){$('#dialog').classList.remove('help-dialog');if(!nested){dialogTrail=[];dialogReturn=document.activeElement}else dialogTrail.push($('#dialog').innerHTML);$('#dialog').innerHTML=`<div class="modal-head"><div class="grow">${nested?'<button class="linkbtn small" data-action="dialog-back" style="margin-bottom:10px">← 返回上一条详情</button>':''}<h2 id="dialog-title">${esc(title)}</h2></div><button class="icon-btn" data-action="dialog-close" aria-label="关闭详情">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!$('#dialog').open)$('#dialog').showModal();$('#dialog').scrollTop=0;$('#dialog').querySelector('input,select,textarea,button')?.focus()}
function closeDialog(){$('#dialog').close();dialogTrail=[];if(dialogReturn?.isConnected)dialogReturn.focus();else $('#content').focus({preventScroll:true})}
function pageHelp(){
  const help=pageHelpContent[S().view],title=sections.find(([id])=>id===S().view)[1];
  showDialog(`${title} · 使用帮助`,`<div class="usage-help"><section><h3>这一步做什么</h3><p>${esc(help.purpose)}</p></section><section><h3>你要做什么</h3><p>${esc(help.action)}</p></section><section><h3>在整个流程里</h3><p>${esc(help.role)}</p></section><section class="help-example"><h3>举个例子</h3><p>${esc(help.example)}</p></section>${help.note?`<p class="help-note">${esc(help.note)}</p>`:''}</div>`,`<button data-action="dialog-close">返回当前页面</button>`);
  $('#dialog').classList.add('help-dialog');
  $('#dialog [data-action="dialog-close"]').setAttribute('aria-label','关闭使用帮助');
}
function detail(key,id){const nested=$('#dialog').open;let x=key==='knowledge'?arr(D().knowledge_base)[0]:byId(key,id);if(!x)return;let title=x.title||x.text||x.indexed_title||x.id||'知识库对照';let body='';if(key==='sources'){body=`<div class="row wrap">${tag(L(x.read_level),'blue')}<span class="mono muted">${esc(x.id)}</span></div><dl class="details-list"><div><dt>研究摘要</dt><dd>${textValue(x.excerpt_or_summary)}</dd></div><div><dt>原始来源</dt><dd>${/^https?:\/\//.test(x.url||'')?`<a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">打开来源原页 ↗</a>`:'未记录可访问地址'}<p class="small muted mt">作者：${esc(arr(x.authors).join('；')||'未记录')}<br>发布日期：${esc(x.published_at||'未记录')} · 读取日期：${esc(x.accessed_at||'未记录')}</p></dd></div><div><dt>证据定位</dt><dd>${textValue(x.locator)}</dd></div><div><dt>研究局限</dt><dd>${textValue(x.limitations)}</dd></div><div><dt>质量核验</dt><dd>${textValue(x.quality)}</dd></div></dl>`}
else if(key==='claims'){body=`<span class="mono muted">${esc(x.id)}</span><dl class="details-list"><div><dt>主张</dt><dd>${esc(x.text)}</dd></div><div><dt>允许表达</dt><dd>${textValue(x.allowed_expression)}</dd></div><div><dt>禁止表达</dt><dd>${textValue(x.forbidden_expression)}</dd></div><div><dt>人群与场景</dt><dd>${textValue(x.population)}<p class="mt">${esc(x.context)}</p></dd></div><div><dt>时间范围</dt><dd>${textValue(x.time_scale)}</dd></div><div><dt>来源及其作用</dt><dd>${arr(x.source_refs).map(r=>`<div style="padding:8px 0"><span class="small muted">${esc(L(r.role))} · ${esc(r.locator||'定位见来源详情')}</span>${refs('sources',[r.source_id],'来源 ')}</div>`).join('')}</dd></div></dl>`}
else if(key==='gaps'){title='待补证项';body=`<div class="row wrap"><span class="mono muted">${esc(x.id)}</span>${tag(x.critical?'关键缺口':'待处理','warn')}</div><h3 class="mt">${esc(x.description)}</h3><dl class="details-list"><div><dt>当前状态</dt><dd>未关闭</dd></div><div><dt>关联范围</dt><dd>${esc(x.scope_id)}</dd></div><div><dt>已有进展／关闭说明</dt><dd>${textValue(x.closure_note)}</dd></div></dl><div class="note mt">需要取得真实材料并重新审阅；生成交接要求不算补证完成。</div>`}
else if(key==='signals'){title=x.indexed_title||`${x.platform} 平台线索`;body=`<div class="row wrap">${tag(x.platform)}${tag('兴趣未知','warn')}</div><div class="note warn mt">目前仅为索引或受限访问线索，不能用来判定内容热度。</div><dl class="details-list"><div><dt>未核验原因</dt><dd>${textValue(x.missing_reason)}</dd></div><div><dt>日期与账号</dt><dd>发布时间：${esc(x.published_at||'未知')}<br>账号：${esc(x.account||'未知')}</dd></div><div><dt>互动指标</dt><dd>${textValue(x.metrics?Object.fromEntries(Object.entries(x.metrics).map(([k,v])=>[({views:'播放量',likes:'点赞数',comments:'评论数'})[k]||k,v])):'未知')}</dd></div><div><dt>受众地区</dt><dd>${textValue(x.audience_region)}</dd></div><div><dt>线索链接</dt><dd>${/^https?:\/\//.test(x.url||'')?`<a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">查看平台原页 ↗</a>`:'未记录'}</dd></div></dl>`}
else if(key==='snapshots'){title='冻结记录详情';body=`<span class="mono">${esc(x.id)}</span><dl class="details-list">${[['类型',L(x.kind)],['状态',L(x.status)],['输入版本',x.input_revision],['记录时间',x.created_at],['记录者',x.actor_label||'主控代理'],['状态说明',x.invalidation_reason||'当前记录中无失效说明'],['关联决定',x.decision_ids]].map(([t,v])=>`<div><dt>${t}</dt><dd>${textValue(v)}</dd></div>`).join('')}</dl><div class="note mt">完整审计载荷保留在原始研究包中。</div>`}
else if(key==='knowledge'){title='知识库对照记录';body=textValue(x)}
showDialog(title,body,'',nested)}
function reviewForm(){const b=byId('branches',S().branch),draft=S().drafts[b.id];showDialog('记录审阅意见',`<p class="small muted">${esc(b.title)}</p><div class="note mt">此处体验审阅动作。草稿仅本页有效，不改变研究准入或真实记录。</div><form id="review-form" class="stack mt"><div class="field"><label for="review-decision">处理意见</label><select id="review-decision"><option value="gap" ${draft?.action==='gap'?'selected':''}>保留，继续补证</option><option value="adjust" ${draft?.action==='adjust'?'selected':''}>调整表达，再审阅</option><option value="reject" ${draft?.action==='reject'?'selected':''}>本轮暂不采用</option></select></div><div class="field"><label for="review-reason">理由与待解决问题 <span class="muted">· 必填</span></label><textarea id="review-reason" placeholder="写下你依据哪条材料做出判断，以及仍需补齐什么。" required>${esc(draft?.reason||'')}</textarea></div><p class="error" id="review-error" role="alert"></p></form>`,`<button data-action="dialog-close">取消</button><button data-action="save-review">保存演示草稿</button><button class="primary" data-action="save-review-next">保存并继续 ${icon('arrow')}</button>`)}
function saveReview(next){const reason=$('#review-reason').value.trim();if(!reason){$('#review-error').textContent='请填写审阅理由，便于后续追溯。';$('#review-reason').focus();return}const s=S(),b=byId('branches',s.branch);s.drafts[b.id]={action:$('#review-decision').value,reason};const i=D().branches.indexOf(b);if(next&&i<D().branches.length-1){s.branch=D().branches[i+1].id;s.branchTab='overview'}else{s.branchTab='records'}closeDialog();render();$('#content').focus({preventScroll:true});toast(next&&i===D().branches.length-1?'已到最后一支。演示草稿已保留，真实研究记录未改动。':'演示草稿已保留，仅当前页面有效。')}
function requestPreview(){const s=S();if(s.selected.size<1||s.selected.size>2)return;showDialog('补证交接预览',`<div class="row wrap">${tag('未发送 · 未执行','blue')}<span class="small muted">交给研究执行方的要求</span></div><h3 class="mt">${esc(D().task.topic)}</h3><ol class="step-list mt">${[...s.selected].map(id=>`<li><div><span class="mono muted">${esc(id)}</span><p>${esc(byId('gaps',id).description)}</p></div></li>`).join('')}</ol><div class="note mt">每个目标需要交回：可追溯来源、取得的证据、适用限制，以及仍未解决的部分。仅使用公开免费路线；具体执行额度需按当前轮次核对，不因生成本预览重置预算。</div><p class="small muted mt">原型只演示如何交接；这一步不会启动研究或关闭缺口。</p>`,`<button data-action="dialog-close">返回调整</button>`)}
function newTask(){const draft=S().draftTask||{};showDialog('新建研究任务',`<div class="note">先体验如何确定范围。原型不会创建真实任务或自动开始研究。</div><form id="new-task-form" class="stack mt"><div class="field"><label for="new-topic">想研究什么？</label><input id="new-topic" required placeholder="例如：频繁清洁与皮肤紧绷的关系" value="${esc(draft.topic||'')}"></div><div class="field"><label for="new-mode">从哪里开始研究？</label><select id="new-mode"><option value="behavior" ${draft.mode==='behavior'?'selected':''}>从行为出发 · 行为型</option><option value="result" ${draft.mode==='result'?'selected':''}>从表象或结果出发 · 结果型</option></select><span class="help">行为型追问“这样做有什么影响”；结果型追问“这个现象有哪些可能原因”。</span></div><div class="field"><label for="new-objective">这次最想回答的问题</label><textarea id="new-objective" required placeholder="用一句话说明希望研究澄清什么。">${esc(draft.objective||'')}</textarea></div><div class="field"><label for="new-exclude">明确不做什么？</label><input id="new-exclude" value="${esc(draft.exclude||'不做个体诊断、处方及具体品牌推荐')}"></div><p id="new-error" class="error" role="alert"></p></form>`,`<button data-action="dialog-close">取消</button><button class="primary" data-action="new-preview">预览任务范围 ${icon('arrow')}</button>`)}
function newPreview(){const topic=$('#new-topic').value.trim(),objective=$('#new-objective').value.trim();if(!topic||!objective){$('#new-error').textContent='请填写研究主题和最想回答的问题。';(!topic?$('#new-topic'):$('#new-objective')).focus();return}const draft={topic,objective,mode:$('#new-mode').value,exclude:$('#new-exclude').value.trim()};S().draftTask=draft;showDialog('任务范围预览',`<div class="note blue">任务演示草稿 · 尚未创建或开始研究</div><dl class="details-list">${[['研究主题',draft.topic],['模式',draft.mode==='behavior'?'行为型':'结果型'],['核心问题',draft.objective],['排除项',draft.exclude||'尚未填写']].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><p class="small muted mt">正式工作台接入后，这一步将进入任务创建和研究交接；本原型只演示范围确认。</p>`,`<button data-action="new-task">返回编辑</button><button class="primary" data-action="dialog-close">完成预览</button>`)}
let toastTimer;function toast(msg){clearTimeout(toastTimer);$('#toast').textContent=msg;toastTimer=setTimeout(()=>$('#toast').textContent='',5000)}
function closeMenu(){$('#app').classList.remove('menu-open');document.querySelector('[data-action="menu"]').setAttribute('aria-expanded','false');if(window.innerWidth<=800)$('#sidebar').setAttribute('inert','')}
function syncMenu(){if(window.innerWidth>800){$('#sidebar').removeAttribute('inert');$('#app').classList.remove('menu-open')}else if(!$('#app').classList.contains('menu-open'))$('#sidebar').setAttribute('inert','')}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.go){navigate(b.dataset.go,b.dataset.openTab);return}if(b.dataset.tab){const s=S();s[b.dataset.tab]=b.dataset.value;if(b.dataset.tab==='evidenceTab'){s.page=1;s.query=''}render();$(`#tab-${b.dataset.tab}-${b.dataset.value}`)?.focus({preventScroll:true});return}if(b.dataset.branch){S().branch=b.dataset.branch;render();document.querySelector(`[data-branch="${b.dataset.branch}"]`)?.focus({preventScroll:true});return}if(b.dataset.openBranch){S().branch=b.dataset.openBranch;S().branchTab='overview';if($('#dialog').open)closeDialog();navigate('review');return}if(b.dataset.candidate){S().candidate=b.dataset.candidate;render();document.querySelector(`[data-candidate="${b.dataset.candidate}"]`)?.focus({preventScroll:true});return}if(b.dataset.detail){detail(b.dataset.detail,b.dataset.id);return}if(b.dataset.page){S()[b.dataset.page]+=Number(b.dataset.delta);render();document.querySelector('.table-wrap')?.scrollTo(0,0);return}if(b.dataset.branchGaps||b.dataset.candidateGaps){const x=b.dataset.branchGaps?byId('branches',b.dataset.branchGaps):byId('candidates',b.dataset.candidateGaps);const ids=x.gaps||[...arr(x.science_gate?.gap_ids),...arr(x.interest_gate?.gap_ids)];S().gapFilter='ids:'+ids.join(',');S().gapQuery='';S().gapPage=1;navigate('directions','gaps');return}const a=b.dataset.action;if(a==='menu'){$('#app').classList.add('menu-open');$('#sidebar').removeAttribute('inert');b.setAttribute('aria-expanded','true');$('#nav button').focus()}else if(a==='menu-close'){closeMenu();document.querySelector('[data-action="menu"]').focus()}else if(a==='page-help')pageHelp();else if(a==='dialog-close')closeDialog();else if(a==='dialog-back'){const old=dialogTrail.pop();if(old){$('#dialog').innerHTML=old;$('#dialog').scrollTop=0;$('#dialog button')?.focus()}}else if(a==='review-form')reviewForm();else if(a==='save-review'||a==='save-review-next')saveReview(a.endsWith('next'));else if(a==='request-preview')requestPreview();else if(a==='new-task')newTask();else if(a==='new-preview')newPreview();else if(a==='clear-search'){S().query='';S().page=1;render();$('#material-search').focus()}else if(a==='clear-gaps'){S().gapQuery='';S().gapFilter='all';S().gapPage=1;render()}else if(a==='clear-selection'){S().selected.clear();render()}});
document.addEventListener('change',e=>{if(e.target.id==='task-switch'){active=Number(e.target.value);render();toast('已切换研究任务；各任务的浏览位置和演示草稿分别保留。')}else if(e.target.id==='gap-filter'){S().gapFilter=e.target.value;S().gapPage=1;render()}else if(e.target.dataset.gap){const set=S().selected,id=e.target.dataset.gap;if(e.target.checked&&set.size>=2){e.target.checked=false;toast('每次最多选择 2 项；先清除一项再添加。');return}if(e.target.checked)set.add(id);else set.delete(id);$('#selection-count').textContent=`已选 ${set.size} / 2 项 · 仅生成交接预览`;document.querySelector('[data-action="request-preview"]').disabled=!set.size;document.querySelector('[data-action="clear-selection"]').disabled=!set.size}});
document.addEventListener('input',e=>{if(!e.target.dataset.input)return;const key=e.target.dataset.input,id=e.target.id,pos=e.target.selectionStart;S()[key]=e.target.value;S()[key==='query'?'page':'gapPage']=1;render();const input=document.getElementById(id);input.focus({preventScroll:true});try{input.setSelectionRange(pos,pos)}catch{}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#dialog').open)closeMenu();const tab=e.target.closest('[role="tab"]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const list=[...tab.parentElement.querySelectorAll('[role="tab"]')],i=list.indexOf(tab);const next=e.key==='Home'?0:e.key==='End'?list.length-1:(i+(e.key==='ArrowRight'?1:-1)+list.length)%list.length;list[next].click()});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='review-form')saveReview(false);if(e.target.id==='new-task-form')newPreview()});
$('#dialog').addEventListener('cancel',e=>{e.preventDefault();closeDialog()});window.addEventListener('resize',syncMenu);render();syncMenu();
